// Filter merged PRs (closed + merged_at exists)
const items = $input.all();
const commits = items.filter(i => i.json.commit);
const issues = items.filter(i => i.json.issue && !i.json.pull_request);
const prs = items.filter(i => i.json.pull_request && i.json.merged_at);

// Filter last 7 days for PRs
const weekAgo = new Date();
weekAgo.setDate(weekAgo.getDate() - 7);
const recentPRs = prs.filter(pr => {
  const mergedAt = new Date(pr.json.merged_at);
  return mergedAt >= weekAgo;
});

// Build summary data
const summaryData = {
  repo_owner: $('Set Config').item.json.github_repo_owner,
  repo_name: $('Set Config').item.json.github_repo_name,
  language: $('Set Config').item.json.language || 'en',
  week_start: weekAgo.toISOString().split('T')[0],
  week_end: new Date().toISOString().split('T')[0],
  commits: commits.map(c => ({
    message: c.json.commit.message,
    author: c.json.commit.author.name,
    date: c.json.commit.author.date,
    sha: c.json.sha.substring(0, 7)
  })),
  issues: issues.map(i => ({
    title: i.json.title,
    number: i.json.number,
    closed_at: i.json.closed_at,
    closer: i.json.closed_by?.login || 'unknown'
  })),
  prs: recentPRs.map(pr => ({
    title: pr.json.title,
    number: pr.json.number,
    merged_at: pr.json.merged_at,
    author: pr.json.user?.login || 'unknown',
    additions: pr.json.additions,
    deletions: pr.json.deletions
  }))
};

return [{ json: summaryData }];

const data = $input.first().json;
const language = data.language || 'en';

// Language-specific prompts
const prompts = {
  en: `You are a technical writer creating a weekly development summary.

Repository: ${data.repo_owner}/${data.repo_name}
Week: ${data.week_start} to ${data.week_end}

Activity Data:
- ${data.commits.length} commits
- ${data.issues.length} issues closed
- ${data.prs.length} PRs merged

Commits:
${data.commits.map(c => `- ${c.sha}: ${c.message} (${c.author})`).join('\n')}

Closed Issues:
${data.issues.map(i => `- #${i.number}: ${i.title} (closed by @${i.closer})`).join('\n')}

Merged PRs:
${data.prs.map(pr => `- #${pr.number}: ${pr.title} by @${pr.author} (+${pr.additions}/-${pr.deletions} lines)`).join('\n')}

Write a narrative summary in 3 sections:
1. **Highlights** - Key accomplishments this week (2-3 sentences)
2. **Development Activity** - Summarize commits, issues, PRs (1 paragraph)
3. **Impact** - What changed and why it matters (2-3 sentences)

Tone: Professional but conversational. Use Markdown formatting.`,

  fr: `Vous êtes un rédacteur technique créant un résumé hebdomadaire de développement.

Dépôt: ${data.repo_owner}/${data.repo_name}
Semaine: ${data.week_start} à ${data.week_end}

Données d'activité:
- ${data.commits.length} commits
- ${data.issues.length} problèmes fermés
- ${data.prs.length} PRs fusionnées

Commits:
${data.commits.map(c => `- ${c.sha}: ${c.message} (${c.author})`).join('\n')}

Problèmes fermés:
${data.issues.map(i => `- #${i.number}: ${i.title} (fermé par @${i.closer})`).join('\n')}

PRs fusionnées:
${data.prs.map(pr => `- #${pr.number}: ${pr.title} par @${pr.author} (+${pr.additions}/-${pr.deletions} lignes)`).join('\n')}

Écrivez un résumé narratif en 3 sections:
1. **Faits saillants** - Réalisations clés cette semaine (2-3 phrases)
2. **Activité de développement** - Résumez commits, problèmes, PRs (1 paragraphe)
3. **Impact** - Ce qui a changé et pourquoi c'est important (2-3 phrases)

Ton: Professionnel mais conversationnel. Utilisez le formatage Markdown.`
};

return [{
  json: {
    ...data,
    claude_prompt: prompts[language] || prompts.en
  }
}];

const response = $input.first().json;
const narrative = response.content[0].text;
const data = $('Process & Filter Data').item.json;

// Build Discord-formatted message (Markdown)
const discordMessage = `## 📊 Weekly Dev Summary: ${data.repo_owner}/${data.repo_name}
**Week:** ${data.week_start} → ${data.week_end}

${narrative}

---
**Stats:** ${data.commits.length} commits • ${data.issues.length} issues closed • ${data.prs.length} PRs merged`;

// Build Email-formatted message (HTML)
const emailHTML = `
<html>
<head>
  <style>
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; line-height: 1.6; color: #333; }
    h1 { color: #2563eb; border-bottom: 3px solid #2563eb; padding-bottom: 10px; }
    .stats { background: #f3f4f6; padding: 15px; border-radius: 8px; margin: 20px 0; }
    .footer { margin-top: 30px; padding-top: 20px; border-top: 1px solid #e5e7eb; font-size: 0.9em; color: #6b7280; }
  </style>
</head>
<body>
  <h1>📊 Weekly Dev Summary: ${data.repo_owner}/${data.repo_name}</h1>
  <p><strong>Week:</strong> ${data.week_start} → ${data.week_end}</p>

  <div class="stats">
    <strong>Activity:</strong> ${data.commits.length} commits • ${data.issues.length} issues closed • ${data.prs.length} PRs merged
  </div>

  ${narrative.replace(/\n/g, '<br>')}

  <div class="footer">
    Generated by Claude API • <a href="https://github.com/${data.repo_owner}/${data.repo_name}">View Repository</a>
  </div>
</body>
</html>
`;

// Build plain text fallback
const plainText = `Weekly Dev Summary: ${data.repo_owner}/${data.repo_name}\n\nWeek: ${data.week_start} → ${data.week_end}\n\n${narrative}\n\nStats: ${data.commits.length} commits • ${data.issues.length} issues closed • ${data.prs.length} PRs merged`;

return [{
  json: {
    discord_message: discordMessage,
    email_html: emailHTML,
    email_text: plainText,
    email_subject: `📊 ${data.repo_owner}/${data.repo_name} - Weekly Dev Summary (${data.week_end})`
  }
}];
